<script setup lang="ts">
import { onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { app } from '../session'
import { profile } from '../engine/dice'
import type { Ev } from '../rules/state'
// dice thrown across the screen. The number was decided by the host; the throw only shows it.
const c = ref<HTMLCanvasElement>(); const now = ref<Ev | null>(null), done = ref(false); let raf = 0, busy = false
const next = async () => { if (busy) return; const e = app.dice.shift(); if (!e) return; busy = true; now.value = e; done.value = false; await throwIt(e); done.value = true; await new Promise(r => setTimeout(r, app.dice.length ? 420 : 1000)); now.value = null; busy = false; cancelAnimationFrame(raf); const x = c.value?.getContext('2d'); x?.clearRect(0, 0, c.value!.width, c.value!.height); next() }
const throwIt = (e: Ev) => new Promise<void>(res => { const el = c.value; if (!el) { res(); return } const d = Math.min(2, devicePixelRatio || 1), W = el.width = el.clientWidth * d, H = el.height = el.clientHeight * d, x = el.getContext('2d')!; const L = (e.dice ?? []).slice(0, 8); const S = Math.min(46, 30 + 120 / Math.max(3, L.length * 2)) * d * Math.min(1, W / (700 * d) + .35); const dice = L.map((q, i) => profile(q.d, q.v, { x: W / 2 + (i - (L.length - 1) / 2) * S * 2.3, y: H * .5, s: S, w: W, h: H, drop: !!q.drop, hot: q.d === 20 && q.v === 20 && !q.drop, cold: q.d === 20 && q.v === 1 && !q.drop, seed: i })); const t0 = performance.now(), T = app.dice.length ? 520 : 780; const tick = (n: number) => { const t = Math.min(1, (n - t0) / T); x.clearRect(0, 0, W, H); for (const q of dice) q.draw(x, t); if (t < 1) raf = requestAnimationFrame(tick); else res() }; raf = requestAnimationFrame(tick); setTimeout(res, T + 500) })
onMounted(() => watch(() => app.dice.length, () => next(), { immediate: true })); onBeforeUnmount(() => cancelAnimationFrame(raf)); const mod = (e: Ev) => (e.sum ?? '').replace(/^\d+ ?/, '')
</script>
<template><div class="dr" :class="{ on: now }"><canvas ref="c" /><Transition name="p"><div v-if="now && done" class="res" :class="{ ok: now.ok, no: now.ok === false }"><b>{{ now.total }}</b><span><small class="cut">{{ now.who }}{{ now.label ? ', ' + now.label : '' }}</small>{{ mod(now) }}<template v-if="now.t !== 'roll' && now.dc && now.dc < 90"> {{ now.ok ? (now.t === 'attack' ? 'hits' : 'succeeds') : (now.t === 'attack' ? 'misses' : 'fails') }}</template><template v-if="now.crit === 'max'"> critical</template></span></div></Transition></div></template>
<style scoped>.dr{position:absolute;inset:0;right:var(--col,0);pointer-events:none!important;z-index:20}canvas{position:absolute;left:10%;top:14%;width:80%;height:44%}.res{position:absolute;left:50%;top:46%;transform:translateX(-50%);display:flex;align-items:stretch;background:var(--paper);color:var(--ink);max-width:92%}.res b{font:800 52px/.8 var(--serif);padding:13px 16px 17px;background:var(--ink);color:var(--paper)}.res.ok b{background:var(--spot);color:var(--on-spot)}.res span{padding:8px 18px 8px 14px;font-size:17px;display:grid;align-content:center;min-width:0}.res small{font-size:15px;color:var(--ink2)}.p-enter-from,.p-leave-to{opacity:0}.p-enter-active,.p-leave-active{transition:.12s}</style>
